"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base error for every microdb failure."""


class LexError(MicroDBError):
    """Lexical error at a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class ParseError(MicroDBError):
    """Syntax error at a zero-based character offset."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(message)
        self.offset = offset


class SchemaError(MicroDBError):
    """Invalid table schema or row shape."""


class TypeMismatchError(MicroDBError):
    """Operand types are not valid for the operator or function."""


class UnknownColumnError(MicroDBError):
    """A column reference does not exist."""


class AmbiguousColumnError(MicroDBError):
    """A column reference matches more than one column."""


class UnknownTableError(MicroDBError):
    """A table name is not in scope."""


class UnknownFunctionError(MicroDBError):
    """A function name is not defined."""

    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"unknown function {name}")


class ArityError(MicroDBError):
    """A function was called with the wrong number of arguments."""

    def __init__(self, name: str, expected: int, actual: int, at_least: bool = False) -> None:
        self.name = name
        self.expected = expected
        self.actual = actual
        if at_least:
            message = f"{name} expects at least {expected} arguments, got {actual}"
        else:
            message = f"{name} expects {expected} arguments, got {actual}"
        super().__init__(message)


class AggregateError(MicroDBError):
    """An aggregate was used where it is not allowed."""


class GroupingError(MicroDBError):
    """A select item or having clause violates grouping rules."""

"""Value model, three-valued logic, comparison and arithmetic."""

from __future__ import annotations

from microdb.errors import TypeMismatchError

_CMP = {"=", "<>", "<", "<=", ">", ">="}
_ARITH = {"+", "-", "*", "/", "%"}


def type_of(v: object) -> str:
    """Return INT, FLOAT, TEXT, BOOL, or NULL."""
    if v is None:
        return "NULL"
    if type(v) is bool:
        return "BOOL"
    if type(v) is int:
        return "INT"
    if type(v) is float:
        return "FLOAT"
    if type(v) is str:
        return "TEXT"
    raise TypeMismatchError(f"unsupported value {v!r}")


def is_numeric(v: object) -> bool:
    """True for int and float. False for bool and NULL."""
    return type(v) is int or type(v) is float


def and_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued AND. False wins over UNKNOWN."""
    if a is False or b is False:
        return False
    if a is True and b is True:
        return True
    return None


def or_(a: bool | None, b: bool | None) -> bool | None:
    """Three-valued OR. True wins over UNKNOWN."""
    if a is True or b is True:
        return True
    if a is False and b is False:
        return False
    return None


def not_(a: bool | None) -> bool | None:
    """Three-valued NOT. NOT UNKNOWN is UNKNOWN."""
    if a is None:
        return None
    return not a


def compare_eq(a: object, b: object) -> bool | None:
    """Equality. NULL compared with anything, including NULL, is UNKNOWN."""
    if a is None or b is None:
        return None
    if is_numeric(a) and is_numeric(b):
        return a == b  # type: ignore[operator]
    if type(a) is bool and type(b) is bool:
        return a == b
    if type(a) is str and type(b) is str:
        return a == b
    raise TypeMismatchError(f"cannot compare {type_of(a)} and {type_of(b)}")


def compare_lt(a: object, b: object) -> bool | None:
    """Less-than. NULL compared with anything is UNKNOWN."""
    if a is None or b is None:
        return None
    if is_numeric(a) and is_numeric(b):
        return a < b  # type: ignore[operator]
    if type(a) is bool and type(b) is bool:
        return a < b
    if type(a) is str and type(b) is str:
        return a < b
    raise TypeMismatchError(f"cannot compare {type_of(a)} and {type_of(b)}")


def compare(op: str, a: object, b: object) -> bool | None:
    """Compare using section 3.1 and three-valued logic."""
    if op == "=":
        return compare_eq(a, b)
    if op == "<>":
        return not_(compare_eq(a, b))
    if op == "<":
        return compare_lt(a, b)
    if op == "<=":
        return or_(compare_lt(a, b), compare_eq(a, b))
    if op == ">":
        return not_(or_(compare_lt(a, b), compare_eq(a, b)))
    if op == ">=":
        return not_(compare_lt(a, b))
    raise TypeMismatchError(f"unknown comparison {op}")


def negate(a: object) -> object:
    """Numeric negation. NULL stays NULL. Type is preserved."""
    if a is None:
        return None
    if type(a) is int:
        return -a
    if type(a) is float:
        return -a
    raise TypeMismatchError(f"cannot negate {type_of(a)}")


def arith(op: str, a: object, b: object) -> object:
    """Arithmetic. NULL propagates. Division by zero yields NULL."""
    if op not in _ARITH:
        raise TypeMismatchError(f"unknown operator {op}")
    if a is None or b is None:
        return None
    _require_numeric(a, op)
    _require_numeric(b, op)
    if op == "%":
        return _mod(a, b)
    if op == "/":
        return _div(a, b)
    return _add_sub_mul(op, a, b)


def _require_numeric(v: object, op: str) -> None:
    if not is_numeric(v):
        raise TypeMismatchError(f"operator {op} requires numeric operands, got {type_of(v)}")


def _is_zero(v: object) -> bool:
    return v == 0


def _mod(a: object, b: object) -> object:
    if type(a) is not int or type(b) is not int:
        raise TypeMismatchError("modulo requires two INT operands")
    if _is_zero(b):
        return None
    return a % b  # type: ignore[operator]


def _div(a: object, b: object) -> object:
    if _is_zero(b):
        return None
    return float(a) / float(b)  # type: ignore[arg-type]


def _add_sub_mul(op: str, a: object, b: object) -> object:
    if type(a) is int and type(b) is int:
        return _int_op(op, a, b)
    return _float_op(op, float(a), float(b))  # type: ignore[arg-type]


def _int_op(op: str, a: int, b: int) -> int:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    return a * b


def _float_op(op: str, a: float, b: float) -> float:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    return a * b

"""Table schema and row validation."""

from __future__ import annotations

import dataclasses

from microdb.errors import SchemaError

_TYPES = ("INT", "FLOAT", "TEXT", "BOOL")


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


class Table:
    """An in-memory relation. FLOAT columns accept int and store float."""

    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        self._name = name
        self._columns = _validate_columns(columns)
        self._rows = _validate_rows(self._columns, rows)

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        for index, column in enumerate(self._columns):
            if column.name == name:
                return index
        raise SchemaError(f"unknown column {name}")


def _validate_columns(columns: list[Column]) -> list[Column]:
    if not columns:
        raise SchemaError("table has no columns")
    seen: set[str] = set()
    for column in columns:
        if column.type not in _TYPES:
            raise SchemaError(f"invalid column type {column.type}")
        if column.name in seen:
            raise SchemaError(f"duplicate column {column.name}")
        seen.add(column.name)
    return list(columns)


def _validate_rows(columns: list[Column], rows: list[list[object]]) -> list[list[object]]:
    stored: list[list[object]] = []
    width = len(columns)
    for row in rows:
        if len(row) != width:
            raise SchemaError(f"row length {len(row)} does not match {width} columns")
        stored.append([_coerce(column, cell) for column, cell in zip(columns, row)])
    return stored


def _coerce(column: Column, cell: object) -> object:
    if cell is None:
        return None
    if column.type == "INT":
        return _coerce_int(column.name, cell)
    if column.type == "FLOAT":
        return _coerce_float(column.name, cell)
    if column.type == "TEXT":
        return _coerce_text(column.name, cell)
    return _coerce_bool(column.name, cell)


def _coerce_int(name: str, cell: object) -> int:
    if type(cell) is int:
        return cell
    raise SchemaError(f"column {name} expects INT, got {cell!r}")


def _coerce_float(name: str, cell: object) -> float:
    # The only implicit conversion in the engine: INT widens to FLOAT.
    if type(cell) is float:
        return cell
    if type(cell) is int:
        return float(cell)
    raise SchemaError(f"column {name} expects FLOAT, got {cell!r}")


def _coerce_text(name: str, cell: object) -> str:
    if type(cell) is str:
        return cell
    raise SchemaError(f"column {name} expects TEXT, got {cell!r}")


def _coerce_bool(name: str, cell: object) -> bool:
    if type(cell) is bool:
        return cell
    raise SchemaError(f"column {name} expects BOOL, got {cell!r}")

"""Hand-written lexer for the microdb query language."""

from __future__ import annotations

import dataclasses

from microdb.errors import LexError

KEYWORDS = frozenset(
    {
        "SELECT",
        "DISTINCT",
        "FROM",
        "INNER",
        "LEFT",
        "JOIN",
        "ON",
        "WHERE",
        "GROUP",
        "BY",
        "HAVING",
        "ORDER",
        "ASC",
        "DESC",
        "LIMIT",
        "OFFSET",
        "AS",
        "AND",
        "OR",
        "NOT",
        "IS",
        "NULL",
        "TRUE",
        "FALSE",
    }
)

_TWO_CHAR = {"<>", "<=", ">="}
_ONE_CHAR = set("=<>+-*/%(),.")


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    value: object
    start: int
    end: int


def tokenize(sql: str) -> list[Token]:
    """Tokenize *sql*. Keywords are case-insensitive; identifiers are not."""
    return _Lexer(sql).run()


class _Lexer:
    def __init__(self, sql: str) -> None:
        self.sql = sql
        self.n = len(sql)
        self.i = 0
        self.tokens: list[Token] = []

    def run(self) -> list[Token]:
        while self.i < self.n:
            self._skip_gap()
            if self.i >= self.n:
                break
            self._scan_one()
        self.tokens.append(Token("EOF", None, self.n, self.n))
        return self.tokens

    def _skip_gap(self) -> None:
        while self.i < self.n:
            ch = self.sql[self.i]
            if ch.isspace():
                self.i += 1
                continue
            if ch == "-" and self.i + 1 < self.n and self.sql[self.i + 1] == "-":
                self.i += 2
                while self.i < self.n and self.sql[self.i] != "\n":
                    self.i += 1
                continue
            return

    def _scan_one(self) -> None:
        ch = self.sql[self.i]
        if _is_digit(ch) or (ch == "." and self.i + 1 < self.n and _is_digit(self.sql[self.i + 1])):
            self.tokens.append(self._number())
            return
        if ch == "'":
            self.tokens.append(self._string())
            return
        if _is_ident_start(ch):
            self.tokens.append(self._ident())
            return
        if ch in _ONE_CHAR:
            self.tokens.append(self._operator())
            return
        raise LexError(f"unexpected character {ch!r}", self.i)

    def _number(self) -> Token:
        start = self.i
        is_float = self._scan_number_body()
        lexeme = self.sql[start:self.i]
        if is_float:
            return Token("FLOAT", float(lexeme), start, self.i)
        return Token("INT", int(lexeme), start, self.i)

    def _scan_number_body(self) -> bool:
        is_float = False
        if self.sql[self.i] == ".":
            self.i += 1
            self._digits()
            is_float = True
        else:
            self._digits()
            is_float = self._scan_fraction()
        if _exponent_at(self.sql, self.i):
            self._exponent()
            is_float = True
        return is_float

    def _scan_fraction(self) -> bool:
        if self.i >= self.n or self.sql[self.i] != ".":
            return False
        nxt = self.i + 1
        if nxt < self.n and _is_digit(self.sql[nxt]):
            self.i += 1
            self._digits()
            return True
        if _exponent_at(self.sql, nxt):
            self.i += 1
            return True
        # `digits.` is a float, including `1.`.
        self.i += 1
        return True

    def _digits(self) -> None:
        if self.i >= self.n or not _is_digit(self.sql[self.i]):
            raise LexError("invalid number", self.i)
        while self.i < self.n and _is_digit(self.sql[self.i]):
            self.i += 1

    def _exponent(self) -> None:
        self.i += 1
        if self.i < self.n and self.sql[self.i] in "+-":
            self.i += 1
        self._digits()

    def _string(self) -> Token:
        start = self.i
        self.i += 1
        chars: list[str] = []
        while self.i < self.n:
            ch = self.sql[self.i]
            if ch == "'":
                if self.i + 1 < self.n and self.sql[self.i + 1] == "'":
                    chars.append("'")
                    self.i += 2
                    continue
                self.i += 1
                return Token("TEXT", "".join(chars), start, self.i)
            chars.append(ch)
            self.i += 1
        raise LexError("unterminated string", start)

    def _ident(self) -> Token:
        start = self.i
        self.i += 1
        while self.i < self.n and _is_ident_cont(self.sql[self.i]):
            self.i += 1
        text = self.sql[start:self.i]
        if text.upper() in KEYWORDS:
            return Token("KEYWORD", text.upper(), start, self.i)
        return Token("IDENT", text, start, self.i)

    def _operator(self) -> Token:
        start = self.i
        two = self.sql[start:start + 2]
        if two in _TWO_CHAR:
            self.i += 2
            return Token("OP", two, start, self.i)
        self.i += 1
        return Token("OP", self.sql[start], start, self.i)


def _is_digit(ch: str) -> bool:
    return "0" <= ch <= "9"


def _is_ident_start(ch: str) -> bool:
    return ch == "_" or ("A" <= ch <= "Z") or ("a" <= ch <= "z")


def _is_ident_cont(ch: str) -> bool:
    return _is_ident_start(ch) or _is_digit(ch)


def _exponent_at(text: str, index: int) -> bool:
    n = len(text)
    if index >= n or text[index] not in "eE":
        return False
    j = index + 1
    if j < n and text[j] in "+-":
        j += 1
    return j < n and _is_digit(text[j])

"""Recursive-descent parser. Keywords are case-insensitive."""

from __future__ import annotations

import dataclasses
from dataclasses import replace

from microdb.aggregate import is_aggregate_name
from microdb.errors import ParseError
from microdb.lexer import Token, tokenize

# Choice: a predicate comparison is not associative, so `1 < 2 < 3` is a ParseError.
# Choice: `1.e3` is one float when the exponent is complete; otherwise `1.` is the float.


@dataclasses.dataclass(frozen=True)
class Literal:
    value: object
    source: str


@dataclasses.dataclass(frozen=True)
class ColumnRef:
    table: str | None
    name: str
    source: str


@dataclasses.dataclass(frozen=True)
class BinaryOp:
    op: str
    left: Expr
    right: Expr
    source: str


@dataclasses.dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: Expr
    source: str


@dataclasses.dataclass(frozen=True)
class IsNull:
    operand: Expr
    negated: bool
    source: str


@dataclasses.dataclass(frozen=True)
class FuncCall:
    name: str
    args: tuple[Expr, ...]
    star: bool
    source: str


Expr = Literal | ColumnRef | BinaryOp | UnaryOp | IsNull | FuncCall


@dataclasses.dataclass(frozen=True)
class SelectItem:
    kind: str
    expr: Expr | None
    alias: str | None
    table: str | None
    source: str


@dataclasses.dataclass(frozen=True)
class JoinClause:
    kind: str
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class OrderItem:
    expr: Expr
    direction: str


@dataclasses.dataclass(frozen=True)
class Query:
    distinct: bool
    items: tuple[SelectItem, ...]
    table: str
    join: JoinClause | None
    where: Expr | None
    group_by: tuple[Expr, ...]
    having: Expr | None
    order_by: tuple[OrderItem, ...]
    limit: int | None
    offset: int | None


_CMP = {"=", "<>", "<", "<=", ">", ">="}


def parse(sql: str) -> Query:
    """Parse a query string into a Query AST."""
    return _Parser(tokenize(sql), sql).parse_query()


class _Parser:
    def __init__(self, tokens: list[Token], sql: str) -> None:
        self.tokens = tokens
        self.sql = sql
        self.pos = 0
        self.agg_depth = 0

    def parse_query(self) -> Query:
        self._expect_kw("SELECT")
        distinct = self._match_kw("DISTINCT")
        items = self._select_list()
        self._expect_kw("FROM")
        table = self._expect_ident()
        join = self._join()
        where = self._optional_clause("WHERE")
        group_by = self._group_by()
        having = self._optional_clause("HAVING")
        order_by = self._order_by()
        limit = self._int_clause("LIMIT")
        offset = self._int_clause("OFFSET")
        self._expect_eof()
        return Query(distinct, items, table, join, where, group_by, having, order_by, limit, offset)

    def _select_list(self) -> tuple[SelectItem, ...]:
        items = [self._select_item()]
        while self._match_op(","):
            items.append(self._select_item())
        return tuple(items)

    def _select_item(self) -> SelectItem:
        if self._is_star_item():
            return self._star_item()
        start = self._peek().start
        expr = self._or()
        alias = self._alias()
        return SelectItem("expr", expr, alias, None, self._span(start))

    def _is_star_item(self) -> bool:
        if self._at_op("*"):
            return True
        return self._peek().kind == "IDENT" and self._ahead(1, "OP", ".") and self._ahead(2, "OP", "*")

    def _star_item(self) -> SelectItem:
        start = self._peek().start
        if self._at_op("*"):
            self._advance()
            return SelectItem("star", None, None, None, self._span(start))
        table = self._expect_ident()
        self._expect_op(".")
        self._expect_op("*")
        return SelectItem("table_star", None, None, table, self._span(start))

    def _alias(self) -> str | None:
        if not self._match_kw("AS"):
            return None
        return self._expect_ident()

    def _join(self) -> JoinClause | None:
        kind = self._join_kind()
        if kind is None:
            return None
        self._expect_kw("JOIN")
        table = self._expect_ident()
        self._expect_kw("ON")
        return JoinClause(kind, table, self._or())

    def _join_kind(self) -> str | None:
        if self._match_kw("INNER"):
            return "INNER"
        if self._match_kw("LEFT"):
            return "LEFT"
        return None

    def _optional_clause(self, keyword: str) -> Expr | None:
        if not self._match_kw(keyword):
            return None
        return self._or()

    def _group_by(self) -> tuple[Expr, ...]:
        if not self._match_kw("GROUP"):
            return ()
        self._expect_kw("BY")
        exprs = [self._or()]
        while self._match_op(","):
            exprs.append(self._or())
        return tuple(exprs)

    def _order_by(self) -> tuple[OrderItem, ...]:
        if not self._match_kw("ORDER"):
            return ()
        self._expect_kw("BY")
        items = [self._order_item()]
        while self._match_op(","):
            items.append(self._order_item())
        return tuple(items)

    def _order_item(self) -> OrderItem:
        expr = self._or()
        if self._match_kw("DESC"):
            return OrderItem(expr, "DESC")
        self._match_kw("ASC")
        return OrderItem(expr, "ASC")

    def _int_clause(self, keyword: str) -> int | None:
        if not self._match_kw(keyword):
            return None
        tok = self._peek()
        if tok.kind != "INT":
            raise ParseError(f"{keyword} expects an integer", tok.start)
        self._advance()
        return int(tok.value)  # type: ignore[arg-type]

    def _or(self) -> Expr:
        start = self._peek().start
        left = self._and()
        while self._match_kw("OR"):
            right = self._and()
            left = BinaryOp("OR", left, right, self._span(start))
        return left

    def _and(self) -> Expr:
        start = self._peek().start
        left = self._not()
        while self._match_kw("AND"):
            right = self._not()
            left = BinaryOp("AND", left, right, self._span(start))
        return left

    def _not(self) -> Expr:
        if not self._match_kw("NOT"):
            return self._predicate()
        start = self.tokens[self.pos - 1].start
        return UnaryOp("NOT", self._not(), self._span(start))

    def _predicate(self) -> Expr:
        start = self._peek().start
        left = self._additive()
        if self._peek().kind == "OP" and self._peek().value in _CMP:
            op = str(self._advance().value)
            return BinaryOp(op, left, self._additive(), self._span(start))
        if self._match_kw("IS"):
            negated = self._match_kw("NOT")
            self._expect_kw("NULL")
            return IsNull(left, negated, self._span(start))
        return left

    def _additive(self) -> Expr:
        return self._binary_level(self._multiplicative, {"+", "-"})

    def _multiplicative(self) -> Expr:
        return self._binary_level(self._unary, {"*", "/", "%"})

    def _binary_level(self, lower: object, ops: set[str]) -> Expr:
        start = self._peek().start
        left = lower()  # type: ignore[operator]
        while self._peek().kind == "OP" and self._peek().value in ops:
            op = str(self._advance().value)
            right = lower()  # type: ignore[operator]
            left = BinaryOp(op, left, right, self._span(start))
        return left

    def _unary(self) -> Expr:
        if not self._at_op("-"):
            return self._primary()
        start = self._peek().start
        self._advance()
        return UnaryOp("-", self._unary(), self._span(start))

    def _primary(self) -> Expr:
        tok = self._peek()
        if tok.kind in {"INT", "FLOAT", "TEXT"}:
            return self._literal(tok)
        if tok.kind == "KEYWORD" and tok.value in {"TRUE", "FALSE", "NULL"}:
            return self._bool_or_null(tok)
        if tok.kind == "IDENT":
            return self._ident_primary()
        if tok.kind == "OP" and tok.value == "(":
            return self._paren()
        raise ParseError("expected expression", tok.start)

    def _literal(self, tok: Token) -> Expr:
        self._advance()
        return Literal(tok.value, self.sql[tok.start:tok.end])

    def _bool_or_null(self, tok: Token) -> Expr:
        self._advance()
        value: object = {"TRUE": True, "FALSE": False, "NULL": None}[str(tok.value)]
        return Literal(value, self.sql[tok.start:tok.end])

    def _paren(self) -> Expr:
        start = self._peek().start
        self._advance()
        expr = self._or()
        self._expect_op(")")
        return replace(expr, source=self._span(start))

    def _ident_primary(self) -> Expr:
        start = self._peek().start
        name = self._expect_ident()
        if self._match_op("("):
            return self._call(name, start)
        if self._match_op("."):
            column = self._expect_ident()
            return ColumnRef(name, column, self._span(start))
        return ColumnRef(None, name, self._span(start))

    def _call(self, name: str, start: int) -> Expr:
        is_agg = is_aggregate_name(name)
        if is_agg and self.agg_depth > 0:
            raise ParseError("aggregates may not nest", start)
        if is_agg:
            self.agg_depth += 1
        try:
            args, star = self._args(name, start)
        finally:
            if is_agg:
                self.agg_depth -= 1
        return FuncCall(name, tuple(args), star, self._span(start))

    def _args(self, name: str, start: int) -> tuple[list[Expr], bool]:
        if self._match_op("*"):
            if name.lower() != "count":
                raise ParseError("* is only valid in count(*)", start)
            self._expect_op(")")
            return [], True
        args: list[Expr] = []
        if not self._at_op(")"):
            args.append(self._or())
            while self._match_op(","):
                args.append(self._or())
        self._expect_op(")")
        return args, False

    def _span(self, start: int) -> str:
        end = self.tokens[self.pos - 1].end
        return collapse_ws(self.sql[start:end])

    def _peek(self) -> Token:
        return self.tokens[self.pos]

    def _advance(self) -> Token:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def _ahead(self, n: int, kind: str, value: object) -> bool:
        idx = self.pos + n
        if idx >= len(self.tokens):
            return False
        tok = self.tokens[idx]
        return tok.kind == kind and tok.value == value

    def _at_op(self, op: str) -> bool:
        tok = self._peek()
        return tok.kind == "OP" and tok.value == op

    def _match_kw(self, kw: str) -> bool:
        tok = self._peek()
        if tok.kind == "KEYWORD" and tok.value == kw:
            self._advance()
            return True
        return False

    def _match_op(self, op: str) -> bool:
        if not self._at_op(op):
            return False
        self._advance()
        return True

    def _expect_kw(self, kw: str) -> Token:
        if not self._match_kw(kw):
            raise ParseError(f"expected {kw}", self._peek().start)
        return self.tokens[self.pos - 1]

    def _expect_op(self, op: str) -> Token:
        if not self._match_op(op):
            raise ParseError(f"expected {op}", self._peek().start)
        return self.tokens[self.pos - 1]

    def _expect_ident(self) -> str:
        tok = self._peek()
        if tok.kind != "IDENT":
            raise ParseError("expected identifier", tok.start)
        self._advance()
        return str(tok.value)

    def _expect_eof(self) -> None:
        tok = self._peek()
        if tok.kind != "EOF":
            raise ParseError("unexpected token", tok.start)


def collapse_ws(text: str) -> str:
    """Collapse whitespace outside string literals to a single space."""
    out: list[str] = []
    i = 0
    n = len(text)
    in_str = False
    pending = False
    while i < n:
        ch = text[i]
        if in_str:
            i = _copy_string_char(text, i, out)
            if out and out[-1] == "'" and not _escaped_quote(text, i - 1):
                in_str = False
            continue
        if ch == "'":
            _emit_space(out, pending)
            pending = False
            in_str = True
            out.append(ch)
            i += 1
            continue
        if ch == "-" and i + 1 < n and text[i + 1] == "-":
            i += 2
            while i < n and text[i] != "\n":
                i += 1
            pending = True
            continue
        if ch.isspace():
            pending = True
            i += 1
            continue
        _emit_space(out, pending)
        pending = False
        out.append(ch)
        i += 1
    return "".join(out).strip()


def _copy_string_char(text: str, i: int, out: list[str]) -> int:
    out.append(text[i])
    if text[i] == "'" and i + 1 < len(text) and text[i + 1] == "'":
        out.append("'")
        return i + 2
    return i + 1


def _escaped_quote(text: str, end: int) -> bool:
    return end >= 2 and text[end - 2:end] == "''"


def _emit_space(out: list[str], pending: bool) -> None:
    if pending and out:
        out.append(" ")

"""Aggregate functions. NULL inputs are ignored. An empty sum is NULL."""

from __future__ import annotations

from microdb.errors import ArityError, TypeMismatchError
from microdb.value import compare_lt, is_numeric, type_of

_AGGREGATES = frozenset({"count", "sum", "avg", "min", "max"})


def is_aggregate_name(name: str) -> bool:
    """Return True if *name* is an aggregate, case-insensitively."""
    return name.lower() in _AGGREGATES


def eval_aggregate(name: str, star: bool, values: list[object], row_count: int) -> object:
    """Evaluate one aggregate over already-computed per-row values."""
    key = name.lower()
    if key == "count":
        return _count(star, values, row_count)
    if key == "sum":
        return _sum(values)
    if key == "avg":
        return _avg(values)
    if key == "min":
        return _minmax(values, True)
    if key == "max":
        return _minmax(values, False)
    raise TypeMismatchError(f"unknown aggregate {name}")


def _count(star: bool, values: list[object], row_count: int) -> int:
    if star:
        return row_count
    return sum(1 for value in values if value is not None)


def _sum(values: list[object]) -> object:
    total: int | float | None = None
    saw_float = False
    for value in values:
        if value is None:
            continue
        number = _numeric(value, "sum")
        if type(number) is float:
            saw_float = True
        total = number if total is None else total + number
    if total is None:
        return None
    if saw_float:
        return float(total)
    return total


def _avg(values: list[object]) -> object:
    total: int | float = 0
    count = 0
    for value in values:
        if value is None:
            continue
        total += _numeric(value, "avg")
        count += 1
    if count == 0:
        return None
    return total / count


def _minmax(values: list[object], want_min: bool) -> object:
    best: object = None
    started = False
    for value in values:
        if value is None:
            continue
        if not started:
            best = value
            started = True
            continue
        best = _prefer(best, value, want_min)
    return best if started else None


def _prefer(best: object, value: object, want_min: bool) -> object:
    lesser = compare_lt(value, best)
    if want_min and lesser:
        return value
    if not want_min and compare_lt(best, value):
        return value
    return best


def _numeric(value: object, name: str) -> int | float:
    if type(value) is bool or not is_numeric(value):
        raise TypeMismatchError(f"{name} requires numeric input, got {type_of(value)}")
    return value  # type: ignore[return-value]


def check_arity(name: str, actual: int, expected: int, at_least: bool = False) -> None:
    """Raise ArityError naming the function and both counts."""
    if at_least and actual < expected:
        raise ArityError(name.lower(), expected, actual, at_least=True)
    if not at_least and actual != expected:
        raise ArityError(name.lower(), expected, actual)

"""Expression evaluation and grouping equivalence."""

from __future__ import annotations

from collections.abc import Callable

from microdb.aggregate import check_arity, is_aggregate_name
from microdb.errors import (
    AggregateError,
    AmbiguousColumnError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownFunctionError,
    UnknownTableError,
)
from microdb.parser import (
    BinaryOp,
    ColumnRef,
    Expr,
    FuncCall,
    IsNull,
    Literal,
    SelectItem,
    UnaryOp,
)
from microdb.value import arith, compare, is_numeric, negate, not_, type_of

Resolver = Callable[[str | None, str], object]
_SCALARS = frozenset({"concat", "upper", "lower", "length", "abs", "coalesce"})


def evaluate(
    expr: Expr,
    resolve: Resolver,
    aggregates: dict[int, object] | None = None,
    allow_aggregates: bool = False,
) -> object:
    """Evaluate *expr*. Aggregates return precomputed values when allowed."""
    if isinstance(expr, Literal):
        return expr.value
    if isinstance(expr, ColumnRef):
        return resolve(expr.table, expr.name)
    if isinstance(expr, UnaryOp):
        return _unary(expr, resolve, aggregates, allow_aggregates)
    if isinstance(expr, IsNull):
        return _is_null(expr, resolve, aggregates, allow_aggregates)
    if isinstance(expr, BinaryOp):
        return _binary(expr, resolve, aggregates, allow_aggregates)
    if isinstance(expr, FuncCall):
        return _call(expr, resolve, aggregates, allow_aggregates)
    raise TypeMismatchError("unknown expression")


def contains_aggregate(expr: Expr) -> bool:
    """Return True if *expr* contains an aggregate call."""
    found: list[FuncCall] = []
    collect_aggregates(expr, found)
    return bool(found)


def is_aggregate_call(expr: Expr) -> bool:
    """Return True if *expr* itself is an aggregate call."""
    return isinstance(expr, FuncCall) and is_aggregate_name(expr.name)


def collect_aggregates(expr: Expr, found: list[FuncCall]) -> None:
    """Append aggregate calls in *expr* to *found*, including nested scalars."""
    if isinstance(expr, FuncCall):
        if is_aggregate_name(expr.name):
            found.append(expr)
        for arg in expr.args:
            collect_aggregates(arg, found)
        return
    if isinstance(expr, BinaryOp):
        collect_aggregates(expr.left, found)
        collect_aggregates(expr.right, found)
        return
    if isinstance(expr, UnaryOp):
        collect_aggregates(expr.operand, found)
        return
    if isinstance(expr, IsNull):
        collect_aggregates(expr.operand, found)


def equivalent(left: Expr, right: Expr, columns: list[tuple[str | None, str]]) -> bool:
    """Structural equality. Column refs match when they resolve to the same column."""
    if type(left) is not type(right):
        return False
    if isinstance(left, Literal) and isinstance(right, Literal):
        return _same_value(left.value, right.value)
    if isinstance(left, ColumnRef) and isinstance(right, ColumnRef):
        return resolve_binding(columns, left.table, left.name) == resolve_binding(
            columns, right.table, right.name
        )
    if isinstance(left, BinaryOp) and isinstance(right, BinaryOp):
        return _same_binary(left, right, columns)
    if isinstance(left, UnaryOp) and isinstance(right, UnaryOp):
        return left.op == right.op and equivalent(left.operand, right.operand, columns)
    if isinstance(left, IsNull) and isinstance(right, IsNull):
        return left.negated == right.negated and equivalent(left.operand, right.operand, columns)
    if isinstance(left, FuncCall) and isinstance(right, FuncCall):
        return _same_call(left, right, columns)
    return False


def having_valid(
    expr: Expr,
    keys: tuple[Expr, ...],
    columns: list[tuple[str | None, str]],
    explicit: bool,
) -> bool:
    """True when every non-aggregated column is covered by a grouping expression."""
    if explicit and any(equivalent(expr, key, columns) for key in keys):
        return True
    if isinstance(expr, FuncCall) and is_aggregate_name(expr.name):
        return True
    if isinstance(expr, Literal):
        return True
    if isinstance(expr, ColumnRef):
        return False
    return _having_parts(expr, keys, columns, explicit)


def output_name(item: SelectItem) -> str:
    """Alias, else bare column name, else collapsed source text."""
    if item.alias:
        return item.alias
    if isinstance(item.expr, ColumnRef):
        return item.expr.name
    return item.source


def resolve_binding(
    columns: list[tuple[str | None, str]],
    table: str | None,
    name: str,
) -> tuple[str | None, str]:
    """Resolve a column reference to its (qualifier, name) binding."""
    index = _match_index(columns, table, name)
    return columns[index]


def resolve_value(
    columns: list[tuple[str | None, str]],
    row: list[object],
    table: str | None,
    name: str,
) -> object:
    """Resolve a column reference to the value in *row*."""
    return row[_match_index(columns, table, name)]


def require_logic(value: object) -> bool | None:
    """Accept only TRUE, FALSE, or UNKNOWN."""
    if value is None or type(value) is bool:
        return value
    raise TypeMismatchError(f"predicate must be boolean, got {type_of(value)}")


def _unary(expr: UnaryOp, resolve: Resolver, aggs: dict[int, object] | None, allow: bool) -> object:
    value = evaluate(expr.operand, resolve, aggs, allow)
    if expr.op == "NOT":
        return not_(require_logic(value))
    if expr.op == "-":
        return negate(value)
    raise TypeMismatchError(f"unknown unary operator {expr.op}")


def _is_null(expr: IsNull, resolve: Resolver, aggs: dict[int, object] | None, allow: bool) -> bool:
    value = evaluate(expr.operand, resolve, aggs, allow)
    found = value is None
    return not found if expr.negated else found


def _binary(expr: BinaryOp, resolve: Resolver, aggs: dict[int, object] | None, allow: bool) -> object:
    left = evaluate(expr.left, resolve, aggs, allow)
    right = evaluate(expr.right, resolve, aggs, allow)
    if expr.op in {"AND", "OR"}:
        return _logic(expr.op, left, right)
    if expr.op in {"=", "<>", "<", "<=", ">", ">="}:
        return compare(expr.op, left, right)
    return arith(expr.op, left, right)


def _logic(op: str, left: object, right: object) -> bool | None:
    from microdb.value import and_, or_

    a = require_logic(left)
    b = require_logic(right)
    return and_(a, b) if op == "AND" else or_(a, b)


def _call(expr: FuncCall, resolve: Resolver, aggs: dict[int, object] | None, allow: bool) -> object:
    if is_aggregate_name(expr.name):
        return _aggregate_ref(expr, aggs, allow)
    args = [evaluate(arg, resolve, aggs, allow) for arg in expr.args]
    return eval_scalar(expr.name, args)


def _aggregate_ref(expr: FuncCall, aggs: dict[int, object] | None, allow: bool) -> object:
    if not allow:
        raise AggregateError(f"aggregate {expr.name} is not allowed in this clause")
    if aggs is None or id(expr) not in aggs:
        raise AggregateError(f"aggregate {expr.name} was not computed")
    return aggs[id(expr)]


def eval_scalar(name: str, args: list[object]) -> object:
    """Evaluate a scalar function. NULL propagates except in coalesce."""
    key = name.lower()
    if key not in _SCALARS:
        raise UnknownFunctionError(name)
    if key == "concat":
        return _concat(args)
    if key == "coalesce":
        return _coalesce(args)
    if key == "abs":
        return _abs(args)
    if key == "length":
        return _length(args)
    return _case_fold(key, args)


def _concat(args: list[object]) -> object:
    check_arity("concat", len(args), 2, at_least=True)
    parts: list[str] = []
    saw_null = False
    for arg in args:
        if arg is None:
            saw_null = True
            continue
        if type(arg) is not str:
            raise TypeMismatchError(f"concat requires TEXT, got {type_of(arg)}")
        parts.append(arg)
    if saw_null:
        return None
    return "".join(parts)


def _coalesce(args: list[object]) -> object:
    check_arity("coalesce", len(args), 1, at_least=True)
    for arg in args:
        if arg is not None:
            return arg
    return None


def _abs(args: list[object]) -> object:
    check_arity("abs", len(args), 1)
    value = args[0]
    if value is None:
        return None
    if type(value) is int:
        return abs(value)
    if type(value) is float:
        return abs(value)
    raise TypeMismatchError(f"abs requires a numeric value, got {type_of(value)}")


def _length(args: list[object]) -> object:
    check_arity("length", len(args), 1)
    value = args[0]
    if value is None:
        return None
    if type(value) is not str:
        raise TypeMismatchError(f"length requires TEXT, got {type_of(value)}")
    return len(value)


def _case_fold(name: str, args: list[object]) -> object:
    check_arity(name, len(args), 1)
    value = args[0]
    if value is None:
        return None
    if type(value) is not str:
        raise TypeMismatchError(f"{name} requires TEXT, got {type_of(value)}")
    return value.upper() if name == "upper" else value.lower()


def _same_value(left: object, right: object) -> bool:
    if type(left) is not type(right):
        return False
    return left == right


def _same_binary(left: BinaryOp, right: BinaryOp, columns: list[tuple[str | None, str]]) -> bool:
    return left.op == right.op and equivalent(left.left, right.left, columns) and equivalent(
        left.right, right.right, columns
    )


def _same_call(left: FuncCall, right: FuncCall, columns: list[tuple[str | None, str]]) -> bool:
    if left.name.lower() != right.name.lower() or left.star != right.star:
        return False
    if len(left.args) != len(right.args):
        return False
    return all(equivalent(a, b, columns) for a, b in zip(left.args, right.args))


def _having_parts(
    expr: Expr,
    keys: tuple[Expr, ...],
    columns: list[tuple[str | None, str]],
    explicit: bool,
) -> bool:
    parts = _children(expr)
    if not parts:
        return False
    return all(having_valid(part, keys, columns, explicit) for part in parts)


def _children(expr: Expr) -> tuple[Expr, ...]:
    if isinstance(expr, BinaryOp):
        return (expr.left, expr.right)
    if isinstance(expr, UnaryOp):
        return (expr.operand,)
    if isinstance(expr, IsNull):
        return (expr.operand,)
    if isinstance(expr, FuncCall):
        return expr.args
    return ()


def _match_index(columns: list[tuple[str | None, str]], table: str | None, name: str) -> int:
    if table is not None:
        return _qualified(columns, table, name)
    hits = [i for i, col in enumerate(columns) if col[1] == name]
    if not hits:
        raise UnknownColumnError(name)
    if len(hits) > 1:
        raise AmbiguousColumnError(name)
    return hits[0]


def _qualified(columns: list[tuple[str | None, str]], table: str, name: str) -> int:
    known = {col[0] for col in columns if col[0] is not None}
    if table not in known:
        raise UnknownTableError(table)
    hits = [i for i, col in enumerate(columns) if col[0] == table and col[1] == name]
    if not hits:
        raise UnknownColumnError(f"{table}.{name}")
    if len(hits) > 1:
        raise AmbiguousColumnError(f"{table}.{name}")
    return hits[0]

"""Turn a Query into an inspectable pipeline of named stages."""

from __future__ import annotations

import dataclasses
from collections.abc import Iterator

from microdb.expr import collect_aggregates
from microdb.parser import Expr, FuncCall, OrderItem, Query, SelectItem

# Stages follow section 8: scan, join, where, group, aggregate, having,
# project, distinct, order, offset, limit.


@dataclasses.dataclass(frozen=True)
class Scan:
    table: str


@dataclasses.dataclass(frozen=True)
class Join:
    kind: str
    table: str
    on: Expr


@dataclasses.dataclass(frozen=True)
class Where:
    predicate: Expr


@dataclasses.dataclass(frozen=True)
class GroupBy:
    keys: tuple[Expr, ...]
    implicit: bool


@dataclasses.dataclass(frozen=True)
class Aggregate:
    calls: tuple[FuncCall, ...]


@dataclasses.dataclass(frozen=True)
class Having:
    predicate: Expr


@dataclasses.dataclass(frozen=True)
class Project:
    items: tuple[SelectItem, ...]


@dataclasses.dataclass(frozen=True)
class Distinct:
    pass


@dataclasses.dataclass(frozen=True)
class OrderBy:
    items: tuple[OrderItem, ...]


@dataclasses.dataclass(frozen=True)
class Offset:
    count: int


@dataclasses.dataclass(frozen=True)
class Limit:
    count: int


@dataclasses.dataclass(frozen=True)
class Plan:
    """A sequence of named stage objects."""

    stages: tuple[object, ...]

    def __iter__(self) -> Iterator[object]:
        return iter(self.stages)

    def __len__(self) -> int:
        return len(self.stages)

    def __getitem__(self, index: int) -> object:
        return self.stages[index]


def plan(query: Query) -> Plan:
    """Build a pipeline. Does not touch tables or evaluate expressions."""
    stages: list[object] = [Scan(query.table)]
    _add_join(stages, query)
    if query.where is not None:
        stages.append(Where(query.where))
    _add_grouping(stages, query)
    if query.having is not None:
        stages.append(Having(query.having))
    stages.append(Project(query.items))
    if query.distinct:
        stages.append(Distinct())
    if query.order_by:
        stages.append(OrderBy(query.order_by))
    if query.offset is not None:
        stages.append(Offset(query.offset))
    if query.limit is not None:
        stages.append(Limit(query.limit))
    return Plan(tuple(stages))


def _add_join(stages: list[object], query: Query) -> None:
    if query.join is None:
        return
    stages.append(Join(query.join.kind, query.join.table, query.join.on))


def _add_grouping(stages: list[object], query: Query) -> None:
    select_having = _select_having_aggs(query)
    if not query.group_by and not select_having:
        return
    calls = list(select_having)
    for item in query.order_by:
        collect_aggregates(item.expr, calls)
    implicit = not bool(query.group_by)
    stages.append(GroupBy(query.group_by, implicit))
    stages.append(Aggregate(tuple(calls)))


def _select_having_aggs(query: Query) -> list[FuncCall]:
    found: list[FuncCall] = []
    for item in query.items:
        if item.expr is not None:
            collect_aggregates(item.expr, found)
    if query.having is not None:
        collect_aggregates(query.having, found)
    return found

"""Execute a plan. NULL, grouping and ordering follow section 8."""

from __future__ import annotations

import dataclasses
from functools import cmp_to_key

from microdb.aggregate import check_arity, eval_aggregate
from microdb.errors import (
    AggregateError,
    AmbiguousColumnError,
    GroupingError,
    MicroDBError,
    TypeMismatchError,
    UnknownColumnError,
    UnknownTableError,
)
from microdb.expr import (
    contains_aggregate,
    equivalent,
    evaluate,
    having_valid,
    is_aggregate_call,
    output_name,
    require_logic,
    resolve_value,
)
from microdb.parser import Expr, FuncCall, OrderItem, SelectItem
from microdb.planner import (
    Aggregate,
    Distinct,
    GroupBy,
    Having,
    Join,
    Limit,
    Offset,
    OrderBy,
    Plan,
    Project,
    Scan,
    Where,
)
from microdb.schema import Table
from microdb.value import compare_eq, compare_lt

# Choice: with GROUP BY, a SELECT item must itself be an aggregate call or
# equivalent to a grouping expression. `count(*) + 1` is therefore rejected.
# Choice: grouping uses section 3.1 equality, except NULL equals NULL.
# Choice: 1 and 1.0 form one group because they compare equal.
# Choice: ORDER BY matches an output column by name or select-item source
# before it re-evaluates, so an alias wins over an input column.


@dataclasses.dataclass(frozen=True)
class Result:
    columns: list[str]
    rows: list[list[object]]


@dataclasses.dataclass
class _Work:
    columns: list[tuple[str | None, str]]
    rows: list[list[object]]


@dataclasses.dataclass
class _Group:
    key: tuple[object, ...]
    rows: list[list[object]]


class _Engine:
    def __init__(self, tables: dict[str, Table]) -> None:
        self.tables = tables
        self.work = _Work([], [])
        self.groups: list[_Group] = []
        self.agg_maps: list[dict[int, object]] | None = None
        self.grouped = False
        self.explicit_group = False
        self.group_keys: tuple[Expr, ...] = ()
        self.distinct = False
        self.output_names: list[str] = []
        self.output_sources: list[str | None] = []
        self.output_rows: list[list[object]] = []
        self.row_aggs: list[dict[int, object] | None] = []
        self.saved_columns: list[tuple[str | None, str]] = []
        self.saved_rows: list[list[object]] = []

    def apply(self, stage: object) -> None:
        name = "_stage_" + type(stage).__name__
        method = getattr(self, name, None)
        if method is None:
            raise MicroDBError(f"unknown stage {type(stage).__name__}")
        method(stage)

    def result(self) -> Result:
        rows = [list(row) for row in self.output_rows]
        return Result(list(self.output_names), rows)

    def _stage_Scan(self, stage: Scan) -> None:
        self.work = _scan(self._table(stage.table))

    def _stage_Join(self, stage: Join) -> None:
        _reject_aggregate(stage.on, "JOIN")
        self.work = _join(self.work, stage.kind, self._table(stage.table), stage.on)

    def _stage_Where(self, stage: Where) -> None:
        _reject_aggregate(stage.predicate, "WHERE")
        self.work = _filter_rows(self.work, stage.predicate)

    def _stage_GroupBy(self, stage: GroupBy) -> None:
        self.grouped = True
        self.explicit_group = not stage.implicit
        self.group_keys = stage.keys
        for key in stage.keys:
            _reject_aggregate(key, "GROUP BY")
        self.groups = _form_groups(self.work, stage.keys, stage.implicit)

    def _stage_Aggregate(self, stage: Aggregate) -> None:
        rows: list[list[object]] = []
        maps: list[dict[int, object]] = []
        width = len(self.work.columns)
        for group in self.groups:
            maps.append(_agg_map(self.work.columns, group.rows, stage.calls))
            rows.append(group.rows[0] if group.rows else [None] * width)
        self.work = _Work(self.work.columns, rows)
        self.agg_maps = maps

    def _stage_Having(self, stage: Having) -> None:
        if not self.grouped:
            _reject_aggregate(stage.predicate, "HAVING")
            self.work = _filter_rows(self.work, stage.predicate)
            return
        self._check_having(stage.predicate)
        self._filter_groups(stage.predicate)

    def _stage_Project(self, stage: Project) -> None:
        self._check_select(stage.items)
        self.saved_columns = list(self.work.columns)
        self.saved_rows = self.work.rows
        names, sources = _project_names(self.work.columns, stage.items)
        self.output_names = names
        self.output_sources = sources
        self._project_rows(stage.items)

    def _stage_Distinct(self, stage: Distinct) -> None:
        del stage
        self.distinct = True
        kept_rows: list[list[object]] = []
        kept_aggs: list[dict[int, object] | None] = []
        for row, amap in zip(self.output_rows, self.row_aggs):
            if any(_distinct_eq(row, prev) for prev in kept_rows):
                continue
            kept_rows.append(row)
            kept_aggs.append(amap)
        self.output_rows = kept_rows
        self.row_aggs = kept_aggs

    def _stage_OrderBy(self, stage: OrderBy) -> None:
        indexes = list(range(len(self.output_rows)))
        indexes.sort(key=cmp_to_key(lambda i, j: _cmp_indexes(self, stage.items, i, j)))
        self.output_rows = [self.output_rows[i] for i in indexes]
        self.row_aggs = [self.row_aggs[i] for i in indexes]

    def _stage_Offset(self, stage: Offset) -> None:
        self.output_rows = self.output_rows[stage.count:]

    def _stage_Limit(self, stage: Limit) -> None:
        self.output_rows = self.output_rows[:stage.count]

    def _table(self, name: str) -> Table:
        try:
            return self.tables[name]
        except KeyError as exc:
            raise UnknownTableError(name) from exc

    def _check_having(self, predicate: Expr) -> None:
        if having_valid(predicate, self.group_keys, self.work.columns, self.explicit_group):
            return
        raise GroupingError("HAVING references a column that is not grouped or aggregated")

    def _filter_groups(self, predicate: Expr) -> None:
        rows: list[list[object]] = []
        maps: list[dict[int, object]] = []
        assert self.agg_maps is not None
        for row, amap in zip(self.work.rows, self.agg_maps):
            if _is_true(predicate, self.work.columns, row, amap, True):
                rows.append(row)
                maps.append(amap)
        self.work = _Work(self.work.columns, rows)
        self.agg_maps = maps

    def _check_select(self, items: tuple[SelectItem, ...]) -> None:
        if not self.grouped:
            return
        for item in items:
            _check_select_item(item, self.group_keys, self.work.columns, self.explicit_group)

    def _project_rows(self, items: tuple[SelectItem, ...]) -> None:
        maps = self.agg_maps if self.agg_maps is not None else [None] * len(self.work.rows)
        self.output_rows = []
        self.row_aggs = []
        for row, amap in zip(self.work.rows, maps):
            self.output_rows.append(_project_row(self.work.columns, row, items, amap, self.grouped))
            self.row_aggs.append(amap)

    def order_value(self, expr: Expr, index: int) -> object:
        matched = _output_match(self.output_names, self.output_sources, expr.source)
        if matched is not None:
            return self.output_rows[index][matched]
        if self.distinct:
            raise UnknownColumnError(expr.source or "ORDER BY")
        return evaluate(expr, lambda table, name: self._order_resolve(table, name, index), self.row_aggs[index], self.grouped)

    def _order_resolve(self, table: str | None, name: str, index: int) -> object:
        if table is None:
            hits = [i for i, col in enumerate(self.output_names) if col == name]
            if len(hits) > 1:
                raise AmbiguousColumnError(name)
            if len(hits) == 1:
                return self.output_rows[index][hits[0]]
            return resolve_value(self.saved_columns, self.saved_rows[index], None, name)
        return resolve_value(self.saved_columns, self.saved_rows[index], table, name)


def execute(query: str, tables: dict[str, Table]) -> Result:
    """Parse, plan and execute *query* against *tables*."""
    from microdb.parser import parse
    from microdb.planner import plan as build_plan

    return execute_plan(build_plan(parse(query)), tables)


def execute_plan(plan: Plan, tables: dict[str, Table]) -> Result:
    """Execute an already-built plan."""
    engine = _Engine(tables)
    for stage in plan:
        engine.apply(stage)
    return engine.result()


def _scan(table: Table) -> _Work:
    columns = [(table.name, column.name) for column in table.columns]
    rows = [list(row) for row in table.rows]
    return _Work(columns, rows)


def _join(left: _Work, kind: str, right: Table, on: Expr) -> _Work:
    right_cols = [(right.name, column.name) for column in right.columns]
    right_rows = [list(row) for row in right.rows]
    out_cols = left.columns + right_cols
    out_rows: list[list[object]] = []
    for left_row in left.rows:
        out_rows.extend(_join_left(left_row, right_rows, out_cols, right_cols, on, kind))
    return _Work(out_cols, out_rows)


def _join_left(
    left_row: list[object],
    right_rows: list[list[object]],
    out_cols: list[tuple[str | None, str]],
    right_cols: list[tuple[str | None, str]],
    on: Expr,
    kind: str,
) -> list[list[object]]:
    matched: list[list[object]] = []
    for right_row in right_rows:
        combined = left_row + right_row
        if _is_true(on, out_cols, combined, None, False):
            matched.append(combined)
    if matched:
        return matched
    if kind == "LEFT":
        return [left_row + [None] * len(right_cols)]
    return []


def _filter_rows(work: _Work, predicate: Expr) -> _Work:
    kept = [row for row in work.rows if _is_true(predicate, work.columns, row, None, False)]
    return _Work(work.columns, kept)


def _is_true(
    expr: Expr,
    columns: list[tuple[str | None, str]],
    row: list[object],
    aggs: dict[int, object] | None,
    allow: bool,
) -> bool:
    value = evaluate(expr, lambda table, name: resolve_value(columns, row, table, name), aggs, allow)
    return require_logic(value) is True


def _form_groups(work: _Work, keys: tuple[Expr, ...], implicit: bool) -> list[_Group]:
    if implicit:
        return [_Group((), list(work.rows))]
    groups: list[_Group] = []
    for row in work.rows:
        key = tuple(_eval_row(key_expr, work.columns, row) for key_expr in keys)
        found = _find_group(groups, key)
        if found is None:
            groups.append(_Group(key, [row]))
        else:
            found.rows.append(row)
    return groups


def _find_group(groups: list[_Group], key: tuple[object, ...]) -> _Group | None:
    for group in groups:
        if all(_group_eq(left, right) for left, right in zip(group.key, key)):
            return group
    return None


def _group_eq(left: object, right: object) -> bool:
    if left is None or right is None:
        return left is None and right is None
    return compare_eq(left, right) is True


def _eval_row(expr: Expr, columns: list[tuple[str | None, str]], row: list[object]) -> object:
    return evaluate(expr, lambda table, name: resolve_value(columns, row, table, name), None, False)


def _agg_map(
    columns: list[tuple[str | None, str]],
    rows: list[list[object]],
    calls: tuple[FuncCall, ...],
) -> dict[int, object]:
    return {id(call): _one_agg(columns, rows, call) for call in calls}


def _one_agg(columns: list[tuple[str | None, str]], rows: list[list[object]], call: FuncCall) -> object:
    if call.star:
        check_arity(call.name, 0, 0)
        return eval_aggregate(call.name, True, [], len(rows))
    if len(call.args) != 1:
        check_arity(call.name, len(call.args), 1)
    values = [_eval_row(call.args[0], columns, row) for row in rows]
    return eval_aggregate(call.name, False, values, len(rows))


def _project_names(
    columns: list[tuple[str | None, str]],
    items: tuple[SelectItem, ...],
) -> tuple[list[str], list[str | None]]:
    names: list[str] = []
    sources: list[str | None] = []
    for item in items:
        item_names, item_sources = _item_names(columns, item)
        names.extend(item_names)
        sources.extend(item_sources)
    return names, sources


def _item_names(
    columns: list[tuple[str | None, str]],
    item: SelectItem,
) -> tuple[list[str], list[str | None]]:
    if item.kind == "star":
        return [col[1] for col in columns], [None] * len(columns)
    if item.kind == "table_star":
        return _table_star_names(columns, item.table or "")
    source = item.expr.source if item.expr is not None else item.source
    return [output_name(item)], [source]


def _table_star_names(
    columns: list[tuple[str | None, str]],
    table: str,
) -> tuple[list[str], list[str | None]]:
    known = {col[0] for col in columns if col[0] is not None}
    if table not in known:
        raise UnknownTableError(table)
    names = [col[1] for col in columns if col[0] == table]
    return names, [None] * len(names)


def _project_row(
    columns: list[tuple[str | None, str]],
    row: list[object],
    items: tuple[SelectItem, ...],
    aggs: dict[int, object] | None,
    allow: bool,
) -> list[object]:
    values: list[object] = []
    for item in items:
        values.extend(_item_values(columns, row, item, aggs, allow))
    return values


def _item_values(
    columns: list[tuple[str | None, str]],
    row: list[object],
    item: SelectItem,
    aggs: dict[int, object] | None,
    allow: bool,
) -> list[object]:
    if item.kind == "star":
        return list(row)
    if item.kind == "table_star":
        return [row[i] for i, col in enumerate(columns) if col[0] == item.table]
    assert item.expr is not None
    return [evaluate(item.expr, lambda table, name: resolve_value(columns, row, table, name), aggs, allow)]


def _check_select_item(
    item: SelectItem,
    keys: tuple[Expr, ...],
    columns: list[tuple[str | None, str]],
    explicit: bool,
) -> None:
    if item.kind != "expr" or item.expr is None:
        raise GroupingError("star is not valid when grouping")
    if not explicit:
        if contains_aggregate(item.expr) or not _has_column(item.expr):
            if _bare_outside_aggregate(item.expr):
                raise GroupingError("column must appear in an aggregate")
            return
        raise GroupingError("column must appear in an aggregate")
    if is_aggregate_call(item.expr) or any(equivalent(item.expr, key, columns) for key in keys):
        return
    raise GroupingError("select item must be an aggregate or a grouping expression")


def _has_column(expr: Expr) -> bool:
    if isinstance(expr, FuncCall):
        return any(_has_column(arg) for arg in expr.args)
    if isinstance(expr, BinaryOp):
        return _has_column(expr.left) or _has_column(expr.right)
    if isinstance(expr, UnaryOp):
        return _has_column(expr.operand)
    if isinstance(expr, IsNull):
        return _has_column(expr.operand)
    return isinstance(expr, type(_col_sentinel())) and False or _is_col(expr)


def _is_col(expr: Expr) -> bool:
    from microdb.parser import ColumnRef

    return isinstance(expr, ColumnRef)


def _col_sentinel() -> Expr:
    from microdb.parser import Literal

    return Literal(None, "")


def _bare_outside_aggregate(expr: Expr) -> bool:
    from microdb.parser import ColumnRef

    if isinstance(expr, FuncCall) and is_aggregate_call(expr):
        return False
    if isinstance(expr, ColumnRef):
        return True
    if isinstance(expr, BinaryOp):
        return _bare_outside_aggregate(expr.left) or _bare_outside_aggregate(expr.right)
    if isinstance(expr, UnaryOp):
        return _bare_outside_aggregate(expr.operand)
    if isinstance(expr, IsNull):
        return _bare_outside_aggregate(expr.operand)
    if isinstance(expr, FuncCall):
        return any(_bare_outside_aggregate(arg) for arg in expr.args)
    return False


def _reject_aggregate(expr: Expr, clause: str) -> None:
    if contains_aggregate(expr):
        raise AggregateError(f"aggregate function not allowed in {clause}")


def _output_match(names: list[str], sources: list[str | None], source: str) -> int | None:
    hits = [i for i, name in enumerate(names) if name == source]
    for i, item_source in enumerate(sources):
        if item_source is not None and item_source == source and i not in hits:
            hits.append(i)
    if not hits:
        return None
    if len(hits) > 1:
        raise AmbiguousColumnError(source)
    return hits[0]


def _cmp_indexes(engine: _Engine, items: tuple[OrderItem, ...], left: int, right: int) -> int:
    for item in items:
        compared = _cmp_values(engine.order_value(item.expr, left), engine.order_value(item.expr, right))
        if compared == 0:
            continue
        return -compared if item.direction == "DESC" else compared
    return 0


def _cmp_values(left: object, right: object) -> int:
    if left is None and right is None:
        return 0
    if left is None:
        return 1
    if right is None:
        return -1
    if compare_eq(left, right):
        return 0
    if compare_lt(left, right):
        return -1
    return 1


def _distinct_eq(left: list[object], right: list[object]) -> bool:
    return all(_distinct_value_eq(a, b) for a, b in zip(left, right))


def _distinct_value_eq(left: object, right: object) -> bool:
    if left is None or right is None:
        return left is None and right is None
    try:
        return compare_eq(left, right) is True
    except TypeMismatchError:
        return False

